      }
    }
  yy283:
    yych = *++p;
    if (yych <= 0x7F)
      goto yy281;
    if (yych <= 0xBF)
      goto yy279;
    goto yy281;
  yy284:
    yych = *++p;
    if (yych <= 0x9F)
