    if (yych <= 0x8F)
      goto yy285;
    goto yy281;
  yy290:
    yych = *++p;
    if (yych <= 0xE0) {
      if (yych <= '>') {
        if (yych <= 0x00)
          goto yy281;
        if (yych <= '=')
          goto yy279;
      } else {
        if (yych <= 0x7F)
          goto yy279;
        if (yych <= 0xC1)
          goto yy281;
        if (yych <= 0xDF)
          goto yy283;
        goto yy284;
      }
    } else {
      if (yych <= 0xEF) {
        if (yych == 0xED)
          goto yy286;
        goto yy285;
      } else {
        if (yych <= 0xF0)
          goto yy287;
        if (yych <= 0xF3)
          goto yy288;
        if (yych <= 0xF4)
          goto yy289;
        goto yy281;
      }
    }
    ++p;
    { return (bufsize_t)(p - start); }
  }
}
